function previewMint(
    uint256 shares
) public view virtual returns (uint256) {
    uint256 supply = totalSupply();
    return
        supply == 0
            ? 10e18
            : shares.mulDivUp(totalAssets(), supply);
}

function safeTransferFrom(
    address from,
